use semio_framework_os_kernel::sqlite_snapshot::artifact::NativeEncodingBound;
use neural_engine::{Dictionary,Value,Atom};
fn text(b:&mut NativeEncodingBound<'_,'_>,v:&str)->Result<(),String>{b.repeated(v.len(),16)}
fn scalar(b:&mut NativeEncodingBound<'_,'_>,v:&Atom)->Result<(),String>{b.add(256)?;match v{Atom::String(s)=>text(b,s),Atom::Decimal(_)=>b.add(2048),_=>Ok(())}}
fn dictionary(b:&mut NativeEncodingBound<'_,'_>,root:&Dictionary)->Result<(),String>{let mut pending=vec![root];while let Some(d)=pending.pop(){b.check_rows(d.len().checked_add(pending.len()).ok_or("Procedure dictionary frontier overflow")?)?;b.checkpoint()?;for(k,v)in d.iter(){text(b,k)?;b.add(256)?;match v{Value::Atom(v)=>scalar(b,v)?,Value::Dictionary(v)=>pending.push(v)}}}Ok(())}
fn value(b:&mut NativeEncodingBound<'_,'_>,v:&Value)->Result<(),String>{match v{Value::Atom(v)=>scalar(b,v),Value::Dictionary(v)=>dictionary(b,v)}}
/// 📏️ Bounds the optional native path/seed scenes without copying or adding persisted entities.
pub fn local_scenes(s:&super::ProcedureSnapshot,b:&mut NativeEncodingBound<'_,'_>)->Result<(),String>{if let Some(data)=s.flow.local_owner::<crate::ProcedureFlowWorkingData>(){let mut pending=vec![&data.path];while let Some(path)=pending.pop(){b.check_rows(path.steps.len().checked_add(pending.len()).ok_or("Procedure path frontier overflow")?)?;b.checkpoint()?;for step in &path.steps{b.add(1024)?;text(b,&step.id)?;text(b,&step.kind)?;dictionary(b,&step.params)?;b.check_rows(step.bodies.len().checked_add(pending.len()).ok_or("Procedure body frontier overflow")?)?;for(name,path)in &step.bodies{text(b,name)?;pending.push(path);}}}}if let Some(data)=s.text.local_owner::<crate::ProcedureTextWorkingData>(){b.check_rows(data.seed.len())?;b.checkpoint()?;for(k,v)in &data.seed{text(b,k)?;value(b,v)?}}Ok(())}
